//! PHP: the FFI binding `Azul.php` (namespace `Azul`, generated by
//! `doc/src/codegen/v2/lang_php`; needs `ffi.enable`). The Zend extension
//! (`php_api.rs`) only exposes App / Dom / Button, so it cannot build styles.
//!
//! The generated code calls the raw C symbols of `\Azul\Azul::lib()` (an
//! `FFI` instance: `$L->AzCssProperty_textColor(..)`, variant constructors
//! `$L->AzLayoutWidth_px(..)`, enum constants `$L->AzLayoutDisplay_Flex`);
//! PHP FFI builds `CData` values with statements, which the generated
//! `azul_struct` / `azul_union` / `azul_vec` / `azul_str` helpers wrap into
//! expressions.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Item, Module, Prim},
    lang::{item_comments, item_doc, variant_ctor_method, ExprSyntax},
    lower_types::union_tag,
    CodegenBackend, GeneratedFile,
};

/// The PHP printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Php;

/// A single-quoted PHP literal (no `$` interpolation): `\\` and `\'` only.
fn php_str(s: &str) -> String {
    format!("'{}'", s.replace('\\', "\\\\").replace('\'', "\\'"))
}

impl ExprSyntax for Php {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "NAN".to_string(),
            "inf" => "INF".to_string(),
            "-inf" => "-INF".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("azul_str({})", php_str(s)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("$L->Az{class}_{}", snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("$L->Az{ty}_{variant}")),
            EnumShape::Tagged => Doc::call(
                format!("$L->Az{ty}_{}", variant_ctor_method(variant)),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let tag = union_tag(ty, variant).unwrap_or(0);
                let mut all = vec![
                    Doc::text(php_str(&format!("Az{ty}"))),
                    Doc::text(php_str(variant)),
                    Doc::text(tag.to_string()),
                ];
                all.extend(args);
                Doc::call("azul_union", all, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{} => ", php_str(&k))), v]))
            .collect();
        Doc::call(
            "azul_struct",
            vec![
                Doc::text(php_str(&format!("Az{ty}"))),
                Doc::list("[", fields, ", ", "]", false, broken, true),
            ],
            broken,
        )
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("$L->Az{ty}_create()"));
        }
        Doc::call(
            "azul_vec",
            vec![
                Doc::text(php_str(&format!("Az{ty}_copyFromPtr"))),
                Doc::text(php_str(&format!("Az{elem}"))),
                Doc::list("[", items, ", ", "]", false, broken, true),
            ],
            broken,
        )
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("null /* not expressible: {} */", super::block_comment_safe(what)))
    }
}

const HELPERS: &str = r#"function azul_struct(string $type, array $fields)
{
    $value = \Azul\Azul::lib()->new($type);
    foreach ($fields as $name => $field) {
        $value->$name = $field;
    }
    return $value;
}

function azul_union(string $type, string $variant, int $tag, $payload = null)
{
    $value = \Azul\Azul::lib()->new($type);
    $value->$variant->tag = $tag;
    if ($payload !== null) {
        $value->$variant->payload = $payload;
    }
    return $value;
}

// Copies the items into a C array; the C API clones them into the Vec.
function azul_vec(string $copy_fn, string $elem, array $items)
{
    $L = \Azul\Azul::lib();
    $n = count($items);
    $array = $L->new($elem . '[' . $n . ']');
    foreach ($items as $i => $item) {
        $array[$i] = $item;
    }
    return $L->$copy_fn($array, $n);
}

function azul_str(string $s)
{
    $L = \Azul\Azul::lib();
    $n = strlen($s);
    $bytes = $L->new('uint8_t[' . max(1, $n) . ']');
    \FFI::memcpy($bytes, $s, $n);
    return $L->AzString_fromUtf8($bytes, $n);
}
"#;

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Php, item) {
        out.push_str(&format!("// {line}\n"));
    }
    let name = item.name.snake();
    match item_doc(&Php, item) {
        Ok(doc) => out.push_str(&format!(
            "function {name}()\n{{\n    $L = \\Azul\\Azul::lib();\n    return {};\n}}\n",
            render(&doc, "    ", 1)
        )),
        Err(reason) => out.push_str(&format!(
            "// not expressible with the PHP bindings: {reason}\nfunction {name}()\n{{\n    return \
             null;\n}}\n"
        )),
    }
    out
}

impl CodegenBackend for Php {
    fn lang(&self) -> &'static str {
        "php"
    }

    fn display_name(&self) -> &'static str {
        "PHP"
    }

    fn extension(&self) -> &'static str {
        "php"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "<?php\n// Generated by azul-css codegen (PHP). Do not edit by hand.\n// Needs the FFI \
             binding Azul.php (target/codegen) and `php -d ffi.enable=1`.\nrequire_once __DIR__ . \
             '/Azul.php';\n\n",
        );
        out.push_str(HELPERS);
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "<?php\n// Copy target/codegen/Azul.php and libazul here, then: php -d ffi.enable=1 \
             main.php\nrequire_once __DIR__ . '/styles.php';\n",
        );
        for item in &m.items {
            let name = item.name.snake();
            main.push_str(&format!(
                "\n${name} = {name}();\necho '{name}: ' . ${name}->len . \" properties\\n\";\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.php".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.php".to_string(),
                contents: main,
            },
        ]
    }
}
